entries[427031] = { ["name"] = "Heldenhafter Sprung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpringt durch die Luft zu einem Zielort und schmettert mit zerstörerischer Gewalt auf den Boden, sodass alle Gegner innerhalb von 8 Metern (23.5% der Zaubermacht + 23.5% der Angriffskraft) körperlichen Schaden erleiden." }
