entries[427037] = { ["name"] = "Lavablitz", ["text"] = "100 Meter Reichweite\nSofort\nEure kritischen Treffer haben eine Chance, eine Lavaschlange zu beschwören, die Euer Ziel 10 Sek. lang angreift. Die Schlange speit alle 2 Sek. einen Lavablitz, der 208 Vulkanschaden verursacht. Bei jeder dritten Beschwörung werden stattdessen drei Schlangen herbeigerufen.\n\nWenn das Ziel stirbt, verfällt die Schlange in Wut und fügt bis zu 8 Gegnern in der Nähe 385 Vulkanschaden zu." }
