entries[427040] = { ["name"] = "Schädelspalter", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt einem Gegner den Schädel ein und fügt ihm (202.488% der Angriffskraft) körperlichen Schaden zu.\n\n'Schädelspalter' sorgt dafür, dass das Ziel 10 Sek. lang 100% schneller durch 'Verwunden' und 'Tiefe Wunden' ausblutet.\n\nErzeugt 15 Wut." }
entries[427041] = { ["name"] = "Ockerfarbene Traumkralle", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Verspielte Traumkrallen verzieren sich oft selbst mit einer Fülle an Farben, wie sie nur die Herbstzeit zu bieten hat.\"\nQuest:\nEin bisschen Hoffnung ist immer gut\nZone:\nSmaragdgrüner Traum" }
