entries[427161] = { ["name"] = "Essenzspleißung", ["text"] = "50 Meter Reichweite\nSofort\nKanalisieren, um die Essenz Eures Ziels aufzulösen, was im Verlauf von 3 Sek. 5921 Naturschaden verursacht und Euch 18 Sek. lang bis zu 258 Meisterschaft gewährt.\n\nDer Schaden gegen bewegungsunfähige Ziele ist um 30% erhöht." }
