entries[427163] = { ["name"] = "Flammende Pestilenz", ["text"] = "500 Meter Reichweite\nSofort\nKnorrenwurzel lässt Felder aus Erde mit Schattenflamme explodieren und fügt Spielercharakteren innerhalb der Explosion 471404 Schaden zu.\n\nEinige dieser Felder absorbieren die Schattenflammenenergie und bilden daraus inaktive besudelte Treants und besudelte Peitscher." }
entries[427165] = { ["name"] = "Flammende Pestilenz", ["text"] = "500 Meter Reichweite\nSofort\nDas flammengepeinigte Urtum erfüllt die Erde in der Umgebung mit Schattenflamme, wodurch diese nach 3 Sek. explodiert. Die Explosion fügt Gegnern innerhalb von 6 Metern 45 Schattenflammenschaden zu.\n\nManche Erdfelder absorbieren die Schattenflammenenergie und beschwören inaktive besudelte Peitscher." }
