entries[427173] = { ["name"] = "Blutrünstiges Anspringen", ["text"] = "50 Meter Reichweite\nSofort\nDer Tiger fokussiert einen Spielercharakter und springt dann auf diesen zu. Fügt Spielercharakteren innerhalb von 10 Metern um den Einschlagbereich 15 körperlichen Schaden zu, woraufhin diese bluten und 10 Sek. lang alle 1.5 Sek. 8 körperlichen Schaden erleiden." }
entries[427174] = { ["name"] = "Wilde Experimente", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nKernwegkatalysator (2)\nFührt ein riskantes Experiment mit 20 Kräutern Eurer Wahl aus, mit dem Ihr unter Umständen ein neues Rezept entdeckt.\n\nIhr habt alles gelernt, was Ihr durch Experimentieren lernen könnt." }
entries[427175] = { ["name"] = "Blutrünstiges Anspringen", ["text"] = "50 Meter Reichweite\nWirken in 2.5 sek.\nDer Tiger fokussiert einen Spielercharakter und springt dann auf diesen zu. Fügt Spielercharakteren innerhalb von 10 Metern um den Einschlagbereich 15 körperlichen Schaden zu, woraufhin diese bluten und 10 Sek. lang alle 1.5 Sek. 8 körperlichen Schaden erleiden." }
entries[427176] = { ["name"] = "Lichtsauger", ["text"] = "10 Meter Reichweite\nWirken in 1.5 sek.\nZuckende Dunkelbruten entziehen einer Kerze die Flammen, verringern so ihre Hitze um 3 und fügen Spielercharakteren 10 Sek. lang alle 1 Sek. 606112 Schattenschaden zu." }
