entries[427180] = { ["name"] = "Furcht vor der Düsternis", ["text"] = "Sofort\nWenn die Wärme des Kerzenlichts aufgezehrt ist, hüllt die Finsternis den Bereich in Düsterkeit, fügt sämtlichen Spielercharakteren 1939560 Schattenschaden zu und lässt sie 1 Sek. lang vor Furcht fliehen. Dadurch erleiden sie 10 Min. lang 10% mehr Schaden und ihr Tempo wird währenddessen um 5% verringert. Dieser Effekt ist stapelbar." }
