entries[427187] = { ["name"] = "Gestärkte Macht", ["text"] = "Sofort\nAnub'ikkajs Leutnants teilen eindrucksvolle Macht mit ihm, was ihren Schaden um 30% und ihre maximale Gesundheit um 50% erhöht. Dieser Effekt ist stapelbar.\n\nWenn sie besiegt werden, verschwindet diese Macht.." }
