entries[427724] = { ["name"] = "Salaträumer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Zwar wechselt die Aufmerksamkeit der meisten Salamanther ständig frei ihre Ausrichtung, aber dennoch genießt dieser es, seine Umgebung regungslos zu beobachten.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
