entries[427729] = { ["name"] = "Geschmolzene Schlacke", ["text"] = "100 Meter Reichweite\nSofort\n'Lavaeruption' verbrennt Euer Ziel und fügt ihm im Verlauf von 4 Sek. 10% zusätzlichen Schaden zu. Nach Verbrauchen von 'Urzeitliche Welle' treffen außerdem Eure nächsten 2 Einsätze von 'Lavaeruption' bis zu 3 zusätzliche Ziele, die von Eurem 'Flammenschock' betroffen sind, und fügen ihnen 65% des normalen Schadens zu." }
